  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="support-card" aria-labelledby="support-title">
      <h1 id="support-title">Contact support</h1>
      <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>

      <form id="support-form" novalidate>
        <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

        <div class="form-field">
          <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="full-name"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
          >
        </div>

        <div class="form-field">
          <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
          <input
