        field,
        isValid: validateField(field)
      }));
      const firstInvalidField = validationResults.find((result) => !result.isValid);

      if (firstInvalidField) {
        firstInvalidField.field.input.focus();
        return;
      }

      fields.forEach(({ input, errorId }) => removeError(input, errorId));
      form.reset();
      statusMessage.textContent = "Your support request is ready to send.";
    });
