   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="support-card" aria-labelledby="support-title">
       <h1 id="support-title">Contact support</h1>
       <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>

       <form id="support-form" novalidate>
         <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

         <div class="form-field">
           <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="full-name"
             type="text"
             autocomplete="name"
             required
           >
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             required
           >
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span>(optional)</span></label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-help"
           >
           <p class="helper-text" id="phone-help">Use a format like +1 555 123 4567, including country code when applicable.</p>
         </div>

         <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
         <button type="submit">Send support request</button>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");
     const fields = [
       {
         input: document.querySelector("#full-name"),
         errorId: "full-name-error",
         message: "Error: Enter your full name."
       },
       {
         input: document.querySelector("#email"),
         errorId: "email-error",
         message: "Error: Enter a valid email address, like name@example.com."
       }
     ];

     function removeError(input, errorId) {
       const error = document.querySelector(`#${errorId}`);

       input.removeAttribute("aria-invalid");
       input.removeAttribute("aria-describedby");
       if (error) {
         error.remove();
       }
     }

     function showError(input, errorId, message) {
       let error = document.querySelector(`#${errorId}`);

       input.setAttribute("aria-invalid", "true");
       input.setAttribute("aria-describedby", errorId);
       if (!error) {
         error = document.createElement("p");
         error.className = "error-message";
         error.id = errorId;
         input.insertAdjacentElement("afterend", error);
       }

       error.textContent = message;
     }

     function validateField({ input, errorId, message }) {
       if (input.validity.valid) {
         removeError(input, errorId);
         return true;
       }

       showError(input, errorId, message);
       return false;
     }

     fields.forEach((field) => {
       field.input.addEventListener("input", () => {
         if (field.input.getAttribute("aria-invalid") === "true") {
           validateField(field);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.textContent = "";

       const validationResults = fields.map((field) => ({
         field,
         isValid: validateField(field)
       }));
       const firstInvalidField = validationResults.find((result) => !result.isValid);

       if (firstInvalidField) {
         firstInvalidField.field.input.focus();
         return;
       }

       fields.forEach(({ input, errorId }) => removeError(input, errorId));
       form.reset();
       statusMessage.textContent = "Your support request is ready to send.";
     });
   </script>
 </body>
